typedef J=Map<String,dynamic>;
J obj(dynamic x)=>Map<String,dynamic>.from(x as Map);
List<J> rows(dynamic x)=>(x as List? ?? []).map(obj).toList();
int id(J p)=>int.tryParse('${p['id']}')??0;
double numv(dynamic v)=>double.tryParse('$v')??0;
String txt(dynamic x)=>x?.toString()??'';
String money(num value){final s=value.round().toString();return s.replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'),(_)=>',')+' د.ع';}
String norm(String s){const ar='٠١٢٣٤٥٦٧٨٩',fa='۰۱۲۳۴۵۶۷۸۹';for(var i=0;i<10;i++){s=s.replaceAll(ar[i],'$i').replaceAll(fa[i],'$i');}return s.toLowerCase().replaceAll('ي','ی').replaceAll('ك','ک').trim();}
class ApiError implements Exception{final String message;final int code;ApiError(this.message,[this.code=0]);@override String toString()=>message;}
class Api{
 final Dio dio; late final ProductMedia media; String nonce='',csrfName='',csrfHash=''; Future<void> postQueue=Future.value();
 Api():dio=Dio(BaseOptions(baseUrl:origin.endsWith('/')?origin:'$origin/',connectTimeout:const Duration(seconds:15),receiveTimeout:const Duration(seconds:65),followRedirects:false,validateStatus:(_)=>true,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'})){
  if(Uri.parse(origin).scheme!='https')throw StateError('HTTPS required');dio.interceptors.add(CookieManager(CookieJar()));media=ProductMedia(Uri.parse(dio.options.baseUrl));
 }
 String url(String relative)=>Uri.parse(dio.options.baseUrl).resolve(relative).toString();
 Future<J> _decode(Future<Response> f)async{try{final r=await f;final j=obj(r.data is String?jsonDecode(r.data):r.data);if(j['csrf_name']!=null){csrfName=txt(j['csrf_name']);csrfHash=txt(j['csrf_hash']);}if(j['mobile_nonce']!=null)nonce=txt(j['mobile_nonce']);if(r.statusCode!=200||j['success']!=true)throw ApiError(txt(j['message']).isEmpty?'تعذر الاتصال بالخدمة':txt(j['message']),r.statusCode??0);return j;}on ApiError{rethrow;}catch(_){throw ApiError('تعذر الاتصال بالخادم الآمن. تحقق من الاتصال وإعدادات HTTPS.');}}
 Future<J> get(String method,[J? query])=>_decode(dio.get('store_product_showcase/$method',queryParameters:query));
 Future<J> post(String method,J data){final run=postQueue.then((_)async{await get('mobile_session');final payload=<String,dynamic>{...data,'mobile_nonce':nonce};if(csrfName.isNotEmpty)payload[csrfName]=csrfHash;return _decode(dio.post('store_product_showcase/$method',data:payload,options:Options(contentType:Headers.formUrlEncodedContentType)));});postQueue=run.then<void>((_) {},onError:(Object _) {});return run;}
 Future<List<J>> products(List<int> ids)async{if(ids.isEmpty)return [];return rows((await get('mobile_products',{'ids':ids.join(',')}))['items']);}
}
